-- V037: F07 扩充政府采购招标文件合规规则目录，并标记规则来源。

ALTER TABLE PROCUREMENT_TENDER_RULE
    ADD SOURCE VARCHAR(16) DEFAULT 'BUILTIN' NOT NULL;

ALTER TABLE PROCUREMENT_TENDER_RULE
    ADD CONSTRAINT CK_PROC_TENDER_RULE_SOURCE
    CHECK (SOURCE IN ('BUILTIN', 'MANUAL', 'LEARNED'));

-- 将 V036 的旧规则名称/编码迁移到当前目录规范。
UPDATE PROCUREMENT_TENDER_RULE
SET RULE_NAME='指定品牌', MATCH_TYPE='KEYWORD', MATCH_CONTENT='指定品牌', SOURCE='BUILTIN'
WHERE RULE_CODE='F07-BRAND-001';

UPDATE PROCUREMENT_TENDER_RULE
SET RULE_NAME='本市地域限制', MATCH_TYPE='REGEX',
    MATCH_CONTENT='本市(?=企业|注册|设有|服务|纳税|社保|供应商|投标人)', SOURCE='BUILTIN'
WHERE RULE_CODE='F07-REGION-001';

UPDATE PROCUREMENT_TENDER_RULE
SET RULE_NAME='不接受联合体', MATCH_TYPE='KEYWORD', MATCH_CONTENT='不接受联合体', SOURCE='BUILTIN'
WHERE RULE_CODE='F07-EXCLUSIVE-001';

UPDATE PROCUREMENT_TENDER_RULE
SET RULE_CODE='F07-QUAL-001', RULE_NAME='注册资本门槛', MATCH_TYPE='REGEX',
    MATCH_CONTENT='注册资本不低于[^，。；：！？,.!?]{0,10}?万', SOURCE='BUILTIN'
WHERE RULE_CODE='F07-QUALIFICATION-001';

UPDATE PROCUREMENT_TENDER_RULE
SET RULE_CODE='F07-TECH-001', RULE_NAME='指定系列参数', MATCH_TYPE='REGEX',
    MATCH_CONTENT='必须采用[^，。；：！？,.!?]{0,30}?系列', SOURCE='BUILTIN'
WHERE RULE_CODE='F07-TECHNICAL-001';

